const output = [];

for (const item of $input.all()) {
  const data = item.json;

  if (!data.success) {
    output.push({
      json: {
        company_id: data.company_id || null,
        source_url: data.source_url || null,
        job_url: null,
        title: null,
        is_valid: false,
        status: "playwright_discovery_failed",
        reason: data.error || "Unknown Playwright error"
      }
    });

    continue;
  }

  if (!Array.isArray(data.jobs) || data.jobs.length === 0) {
    output.push({
      json: {
        company_id: data.company_id,
        source_url: data.source_url,
        job_url: null,
        title: null,
        is_valid: false,
        status: "no_jobs_found"
      }
    });

    continue;
  }

  for (const job of data.jobs) {
    output.push({
      json: {
        company_id: data.company_id,
        source_url: data.source_url,
        job_url: job.job_url,
        title: job.title,
        is_valid: true,
        status: "job_discovered",
        discovery_method: "playwright"
      }
    });
  }
}

return output;

const item = $input.item.json;
const html = item.html || '';

function cleanText(value) {
  return String(value || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function firstMatch(patterns, text = html) {
  for (const pattern of patterns) {
    const match = pattern.exec(text);

    if (match && match[1]) {
      const value = cleanText(match[1]);

      if (value) {
        return value;
      }
    }
  }

  return null;
}

function parseJsonLdJobPosting() {
  const regex =
    /<script\b[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;

  let match;

  while ((match = regex.exec(html)) !== null) {
    try {
      const data = JSON.parse(match[1].trim());
      const candidates = [];

      function collect(obj) {
        if (!obj || typeof obj !== 'object') {
          return;
        }

        if (Array.isArray(obj)) {
          for (const entry of obj) {
            collect(entry);
          }
          return;
        }

        const type = obj['@type'] || obj.type;

        if (
          type === 'JobPosting' ||
          (Array.isArray(type) && type.includes('JobPosting'))
        ) {
          candidates.push(obj);
        }

        if (Array.isArray(obj['@graph'])) {
          for (const entry of obj['@graph']) {
            collect(entry);
          }
        }
      }

      collect(data);

      if (candidates.length > 0) {
        return candidates[0];
      }
    } catch {
      // Ignore invalid JSON-LD blocks
    }
  }

  return null;
}

function locationFromJsonLd(job) {
  if (!job?.jobLocation) {
    return null;
  }

  const locations = Array.isArray(job.jobLocation)
    ? job.jobLocation
    : [job.jobLocation];

  return (
    locations
      .map((loc) => {
        if (typeof loc === 'string') {
          return loc;
        }

        const address = loc.address || {};

        return [
          address.streetAddress,
          address.addressLocality,
          address.addressRegion,
          address.postalCode,
          address.addressCountry
        ]
          .filter(Boolean)
          .join(', ');
      })
      .filter(Boolean)
      .join(' | ') || null
  );
}

function salaryFromJsonLd(job) {
  const salary = job?.baseSalary || null;

  if (!salary || typeof salary !== 'object') {
    return {};
  }

  const value =
    salary.value && typeof salary.value === 'object'
      ? salary.value
      : salary;

  return {
    salary_min:
      value.minValue != null
        ? Number(value.minValue)
        : value.value != null
          ? Number(value.value)
          : null,

    salary_max:
      value.maxValue != null
        ? Number(value.maxValue)
        : value.value != null
          ? Number(value.value)
          : null,

    currency:
      salary.currency ||
      value.currency ||
      null
  };
}


// ============================================================
// JSON-LD
// ============================================================

const jsonLd = parseJsonLdJobPosting();

let title =
  cleanText(jsonLd?.title) ||
  cleanText(item.title) ||
  null;

let description =
  jsonLd?.description
    ? cleanText(jsonLd.description)
    : null;

let location = locationFromJsonLd(jsonLd);

let jobType =
  jsonLd?.employmentType ||
  null;

let postedAt =
  jsonLd?.datePosted ||
  null;

let expiresAt =
  jsonLd?.validThrough ||
  null;

let applicationUrl =
  jsonLd?.url ||
  null;

const salary = salaryFromJsonLd(jsonLd);


// ============================================================
// TITLE FALLBACK
// ============================================================

if (!title) {
  title = firstMatch([
    /<h1\b[^>]*>([\s\S]*?)<\/h1>/i,
    /<title\b[^>]*>([\s\S]*?)<\/title>/i
  ]);
}


// ============================================================
// DESCRIPTION FALLBACK
// ============================================================

if (!description) {
  description = firstMatch([
    /<(?:div|section|article)\b[^>]*(?:class|id)=["'][^"']*(?:jobDescriptionContent|job-description|job_description|jobDescription|description|job-details|job-details-content|job-content)[^"']*["'][^>]*>([\s\S]*?)<\/(?:div|section|article)>/i,

    /<(?:div|section|article)\b[^>]*(?:class|id)=["'][^"']*(?:description|responsibilities|qualifications|requirements)[^"']*["'][^>]*>([\s\S]*?)<\/(?:div|section|article)>/i,

    /<main\b[^>]*>([\s\S]*?)<\/main>/i,

    /<article\b[^>]*>([\s\S]*?)<\/article>/i
  ]);
}


// ============================================================
// SECTION EXTRACTION
// ============================================================

function extractSection(headingPattern) {
  const regex = new RegExp(
    '<(?:h2|h3|h4|strong|b)[^>]*>' +
      '\\s*([^<]*' +
      headingPattern +
      '[^<]*)\\s*' +
      '<\\/(?:h2|h3|h4|strong|b)>' +
      '[\\s\\S]{0,3000}?' +
      '((?:<ul[\\s\\S]*?<\\/ul>)|' +
      '(?:<ol[\\s\\S]*?<\\/ol>)|' +
      '(?:<p[\\s\\S]*?<\\/p>))',
    'i'
  );

  const match = regex.exec(html);

  if (!match) {
    return [];
  }

  const content = match[2];

  const bullets = [];

  for (const bm of content.matchAll(
    /<li\b[^>]*>([\s\S]*?)<\/li>/gi
  )) {
    const text = cleanText(bm[1]);

    if (text) {
      bullets.push(text);
    }
  }

  if (bullets.length > 0) {
    return bullets;
  }

  const text = cleanText(content);

  return text ? [text] : [];
}

const requirements = extractSection(
  'requirements?|qualifications?|what we[\\s\\S]{0,10}looking for|what you[\\s\\S]{0,10}need|must have|essential skills'
);

const niceToHave = extractSection(
  'preferred qualifications?|preferred skills?|nice to have|bonus|good to have|plus|desirable'
);


// ============================================================
// LOCATION FALLBACK
// ============================================================

if (!location) {
  location = firstMatch([
    /<(?:span|div|p)\b[^>]*(?:class|id)=["'][^"']*(?:jobLocation|job-location|location)[^"']*["'][^>]*>([\s\S]*?)<\/(?:span|div|p)>/i
  ]);
}


// ============================================================
// JOB TYPE FALLBACK
// ============================================================

if (!jobType) {
  jobType = firstMatch([
    /<(?:span|div|p)\b[^>]*(?:class|id)=["'][^"']*(?:employmentType|employment-type|jobType|job-type)[^"']*["'][^>]*>([\s\S]*?)<\/(?:span|div|p)>/i
  ]);
}


// ============================================================
// POSTED DATE FALLBACK
// ============================================================

if (!postedAt) {
  postedAt = firstMatch([
    /<(?:span|div|time)\b[^>]*(?:class|id)=["'][^"']*(?:posted|datePosted|job-date|posted-date)[^"']*["'][^>]*>([\s\S]*?)<\/(?:span|div|time)>/i
  ]);
}


// ============================================================
// APPLICATION URL
// ============================================================

if (!applicationUrl) {
  const applyMatch =
    /<a\b[^>]*href=["']([^"']+)["'][^>]*>[\s\S]{0,150}?(?:apply now|apply for this job|apply)[\s\S]{0,150}?<\/a>/i.exec(
      html
    );

  if (applyMatch) {
    try {
      applicationUrl = new URL(
        applyMatch[1],
        item.job_url
      ).href;
    } catch {
      applicationUrl = null;
    }
  }
}

if (applicationUrl) {
  try {
    applicationUrl = new URL(
      applicationUrl,
      item.job_url
    ).href;
  } catch {
    applicationUrl = null;
  }
}


// ============================================================
// VALIDATION
// ============================================================

if (!description || description.length < 30) {
  return {
    json: {
      ...item,

      // Don't send the entire HTML further through n8n
      html: undefined,

      is_valid: false,
      status: 'job_details_incomplete',

      reason:
        'Could not extract a meaningful job description'
    }
  };
}

if (!title || title.length < 3) {
  return {
    json: {
      ...item,

      html: undefined,

      is_valid: false,
      status: 'job_details_incomplete',

      reason:
        'Could not extract a meaningful job title'
    }
  };
}


// ============================================================
// REMOTE TYPE
// ============================================================

const remoteText =
  [location || '', description || '']
    .join(' ')
    .toLowerCase();

let remoteType = null;

if (
  /\bfully remote\b/.test(remoteText) ||
  /\bremote position\b/.test(remoteText) ||
  /\bwork remotely\b/.test(remoteText) ||
  /\b100% remote\b/.test(remoteText)
) {
  remoteType = 'remote';
}
else if (
  /\bhybrid\b/.test(remoteText)
) {
  remoteType = 'hybrid';
}
else if (
  /\bon[- ]site\b/.test(remoteText) ||
  /\bonsite\b/.test(remoteText) ||
  /\bin office\b/.test(remoteText)
) {
  remoteType = 'on-site';
}


// ============================================================
// FINAL OUTPUT
// ============================================================

return {
  json: {
    company_id: item.company_id,

    source_url: item.source_url,

    job_url: item.job_url,

    title: title.trim(),

    description:
      description
        .substring(0, 20000)
        .trim(),

    location:
      location || null,

    job_type:
      jobType || null,

    remote_type:
      remoteType,

    salary_min:
      salary.salary_min ?? null,

    salary_max:
      salary.salary_max ?? null,

    currency:
      salary.currency || null,

    experience_required:
      null,

    experience_level:
      null,

    requirements,

    nice_to_have:
      niceToHave,

    application_url:
      applicationUrl || item.job_url,

    posted_at:
      postedAt || null,

    expires_at:
      expiresAt || null,

    is_valid:
      true,

    metadata: {
      extraction: {
        strategy: 'json-ld-then-regex',

        detail_page_fetched:
          true,

        json_ld_found:
          Boolean(jsonLd)
      }
    }
  }
};
